// Call of Duty iPad - fonts compiled into the app (resources/fonts, SIL Open
// Font License). The data is generated by CMake (embedded_fonts.cpp).

#pragma once

#include <cstddef>

namespace cod {

struct EmbeddedFont {
  const char* name;  // file name in resources/fonts
  const unsigned char* data;
  size_t size;
};

extern const EmbeddedFont kEmbeddedFonts[];
extern const int kEmbeddedFontCount;

// nullptr when the font is not part of the build.
const EmbeddedFont* FindEmbeddedFont(const char* name);

}  // namespace cod
